            { kind: "read", promptUk: "Чим 403 відрізняється від 401?", promptEn: "How does 403 differ from 401?", language: "http", code: "HTTP/1.1 403 Forbidden", options: ["сервер відмовляється виконати запит, зокрема через брак прав", "клієнт завжди анонімний", "це успішне створення", "це редирект на /v2"], optionsEn: ["The server refuses the request, for example because permission is insufficient", "The client is always anonymous", "It means successful creation", "It is a redirect to /v2"], correctIndex: 0, explanationUk: "403 — відмова; вона не обов'язково означає, що користувач увійшов.", explanationEn: "403 is a refusal; it does not necessarily imply a logged-in user." }
